import json
from docx import Document

TEMPLATE='/root/offer_letter_template.docx'
OUTPUT='/root/offer_letter_filled.docx'
DATA='/root/employee_data.json'

with open(DATA,'r',encoding='utf-8') as f:
    data=json.load(f)

replacements={f"{{{{{k}}}}}": str(v) for k,v in data.items()}

start='{{IF_RELOCATION}}'
end='{{END_IF_RELOCATION}}'
keep_relocation=str(data.get('RELOCATION_PACKAGE','')).strip().lower()=='yes'

# Helper to remove a paragraph from document

def remove_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None


def replace_in_paragraph(paragraph, find_text, replace_text):
    if not find_text:
        return
    # Build full text
    runs = paragraph.runs
    full = ''.join(r.text for r in runs)
    idx = full.find(find_text)
    while idx != -1:
        start_idx = idx
        end_idx = idx + len(find_text)
        # locate run boundaries
        cur = 0
        run_start = run_end = None
        start_in_run = end_in_run = None
        for i, run in enumerate(runs):
            run_text = run.text
            run_len = len(run_text)
            if run_start is None and cur + run_len > start_idx:
                run_start = i
                start_in_run = start_idx - cur
            if run_start is not None and cur + run_len >= end_idx:
                run_end = i
                end_in_run = end_idx - cur
                break
            cur += run_len
        if run_start is None or run_end is None:
            break
        if run_start == run_end:
            run = runs[run_start]
            run.text = run.text[:start_in_run] + replace_text + run.text[end_in_run:]
        else:
            first_run = runs[run_start]
            last_run = runs[run_end]
            first_run.text = first_run.text[:start_in_run] + replace_text + last_run.text[end_in_run:]
            for i in range(run_start + 1, run_end + 1):
                runs[i].text = ''
        full = ''.join(r.text for r in runs)
        idx = full.find(find_text)


def process_paragraphs(paragraphs):
    in_block = False
    for p in list(paragraphs):
        # paragraph might be removed; skip if so
        if p._element is None:
            continue
        text = ''.join(r.text for r in p.runs)

        if start in text:
            if keep_relocation:
                replace_in_paragraph(p, start, '')
            else:
                in_block = True
                if end in text:
                    remove_paragraph(p)
                    in_block = False
                else:
                    remove_paragraph(p)
                continue

        if in_block and not keep_relocation:
            if end in text:
                remove_paragraph(p)
                in_block = False
            else:
                remove_paragraph(p)
            continue

        if end in text:
            if keep_relocation:
                replace_in_paragraph(p, end, '')
            else:
                # End marker while not keeping (handled by in_block)
                continue

        # Replace placeholders
        for find, repl in replacements.items():
            replace_in_paragraph(p, find, repl)


# Load document

doc = Document(TEMPLATE)

# Process main body paragraphs
process_paragraphs(doc.paragraphs)

# Process tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            process_paragraphs(cell.paragraphs)

# Process headers/footers
for section in doc.sections:
    process_paragraphs(section.header.paragraphs)
    process_paragraphs(section.footer.paragraphs)

# Save output

doc.save(OUTPUT)

print('saved', OUTPUT)
PY"}

